<?php
namespace App\Jobs;use App\Models\Booking;use App\Services\WhatsAppGateway;use Illuminate\Bus\Queueable;use Illuminate\Contracts\Queue\ShouldBeUnique;use Illuminate\Contracts\Queue\ShouldQueue;use Illuminate\Foundation\Bus\Dispatchable;use Illuminate\Queue\InteractsWithQueue;use Illuminate\Queue\SerializesModels;use Illuminate\Support\Facades\Log;
class SendBookingCreatedNotification implements ShouldQueue,ShouldBeUnique{use Dispatchable,InteractsWithQueue,Queueable,SerializesModels;public function __construct(public int $bookingId,public string $paymentUrl){}public function uniqueId():string{return(string)$this->bookingId;}public function handle(WhatsAppGateway $wa):void{$b=Booking::with('facility')->find($this->bookingId);if(!$b)return;try{$wa->sendMessage($b->customer_phone,"Booking {$b->booking_number} berhasil dibuat. Silakan lakukan pembayaran sebelum {$b->expires_at?->format('d-m-Y H:i')} WIB.\nFasilitas: {$b->facility->name}\nPembayaran: {$this->paymentUrl}");}catch(\Throwable $e){Log::error('booking created whatsapp failed',['booking_id'=>$b->id,'error'=>$e->getMessage()]);throw $e;}}}
